// Obtener todos los items
const items = $input.all();

// Filtrar asesores que tienen schedules > 0
const advisorsWithSchedules = items.filter(item => {
  const hasSchedules = item.json.schedules > 0;
  return hasSchedules;
});

// Verificar si hay asesores disponibles
if (advisorsWithSchedules.length === 0) {
  return { 
    json: { 
      error: 'No hay asesores con horarios disponibles',
    } 
  };
}

// Seleccionar uno aleatorio
const randomIndex = Math.floor(Math.random() * advisorsWithSchedules.length);
const selectedAdvisor = advisorsWithSchedules[randomIndex].json;

return { 
  json: { 
    advisorId: selectedAdvisor.advisorId, 
    advisorName: selectedAdvisor.advisorName,
    schedules: selectedAdvisor.schedules
  } 
};

const items = $input.all();
if (!items.length) throw new Error('No hay datos de entrada');

let raw = items[0].json;
let cliente;
if (Array.isArray(raw)) {
  if (!raw.length) throw new Error('El array de entrada está vacío');
  cliente = raw[0];
} else {
  cliente = raw;
}
if (!cliente || typeof cliente !== 'object') throw new Error('Formato de entrada inválido');

function getKmFrequency(groupR, modelYear) {
  const year = parseInt(modelYear) || 0;

  switch (groupR) {
    case 1:  return 15000; // KA
    case 2:
    case 3:  return 15000; // FIESTA
    case 4:  return 15000; // ECOSPORT
    case 6:  return 15000; // FOCUS
    case 8:  return 15000; // S-MAX
    case 9:                // RANGER generaciones viejas
      return year >= 2024 ? 16000 : 10000;
    case 11: return 15000; // COURIER
    case 12: return 15000; // KUGA
    case 13: return 15000; // OTROS
    case 14:               // TRANSIT
      return year >= 2021 ? 16000 : 15000;
    case 15: return 15000; // MONDEO
    case 16: return 15000; // MUSTANG
    case 17:
    case 25: return 15000; // F-150 / F-250
    case 18: return 15000; // F-150 RAPTOR
    case 19: return 10000; // TERRITORY
    case 20: return 16000; // BRONCO SPORT
    case 22: return 15000; // MAVERICK
    case 23: return 15000; // CARGO
    case 24: return 16000; // RANGER (P703)
    case 26: return 16000; // MACH-E
    case 27: return 16000; // RANGER RAPTOR (P703)
    case 28: return 16000; // BRONCO
    case 30: return 16000; // EVEREST
    default: return 15000; // fallback general
  }
}

const resultado = {
  customerK:       cliente.customerK ?? null,
  model:           cliente.model || null,
  model_id:        cliente.groupR || null,
  plate:           cliente.plate || null,
  chassi:          cliente.chassi || null,
  nationalId:      cliente.nationalId || null,
  firstname:       cliente.firstname || null,
  lastname:        cliente.lastname || null,
  email:           cliente.email || null,
  id_conversation: String($("When Executed by Another Workflow").first().json.id_conversation),
  company:         3,
  km_frequency:    getKmFrequency(cliente.groupR, cliente.modelYear),
};

return [{ json: resultado }];

// Obtenemos todos los items del input
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) throw new Error('El array raíz está vacío');
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const services = Array.isArray(root.response) ? root.response : [];
if (!services.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// 🔥 Normaliza texto (sin tildes, minúscula)
function normalizeText(text) {
  return (text ?? "")
    .toString()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

const output = [];

for (const svc of services) {
  const serviceNameNorm = normalizeText(svc.serviceName);

  // ❌ Excluir Servicio Móvil (incluye "(Online)")
  if (serviceNameNorm.includes("servicio movil")) {
    continue;
  }

  // ❌ Excluir Lavado Complementario (incluye typo)
  if (
    serviceNameNorm.includes("lavado complementario") ||
    serviceNameNorm.includes("lavado complemetario")
  ) {
    continue;
  }

  // ❌ Excluir Lavado de Cortesía
  if (
    serviceNameNorm.includes("lavado de cortesia") ||
    serviceNameNorm.includes("lavado cortesia")
  ) {
    continue;
  }

  const servicesByModelGroup = Array.isArray(svc.servicesByModelGroup)
    ? svc.servicesByModelGroup
    : [];

  let promo = null;
  for (const mg of servicesByModelGroup) {
    if (mg.promotionalActive) {
      promo = mg;
      break;
    }
  }

  const price = promo && typeof promo.promotionalPrice === 'number'
    ? promo.promotionalPrice
    : svc.servicePrice ?? null;

  const simplified = {
    serviceId: svc.serviceId,
    name: svc.serviceName,
    description: svc.name ?? null,
    price,
    normalPrice: svc.servicePrice ?? null,
    isPromo: !!(promo && promo.promotionalActive),
  };

  output.push({ json: simplified });
}

return output;

