if (!items.length) {
  throw new Error('No hay datos de entrada');
}

// El input viene como:
// [ { httpCode, message, response: [ { ...servicio }, ... ] } ]
let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) {
    throw new Error('El array raíz está vacío');
  }
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const list = Array.isArray(root.response) ? root.response : [];
if (!list.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// Helper para normalizar fechas a "solo día"
function toDateOnly(value) {
  if (!value) return null;
  const d = new Date(value);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}

// Helper para parsear montos (string o number)
function toNumber(value) {
  if (value === null || value === undefined) return 0;
  if (typeof value === 'number') return value;
  const s = String(value).replace(',', '.');
  const n = Number(s);
  return isNaN(n) ? 0 : n;
}

// Fecha actual (Argentina, pero solo día nos alcanza)
const now = new Date();
now.setHours(0, 0, 0, 0);

// Filtramos servicios vigentes hoy
const vigentes = list.filter(item => {
  const start = toDateOnly(item.modelStartDate);
  const end = toDateOnly(item.modelEndDate);
  if (!start || !end) return false;
  return start <= now && now <= end;
});

if (!vigentes.length) {
  throw new Error('No hay servicios vigentes para la fecha actual');
}

// Tomamos el primero vigente (en tu caso el de diciembre)
const svc = vigentes[0];

// Calculamos precio de ítems
const parts = Array.isArray(svc.revisionPartVOs) ? svc.revisionPartVOs : [];

let totalPartsPrice = 0;
const includedItems = parts.map(p => {
  const qty = toNumber(p.quantity);
  const price = toNumber(p.price);
  const subtotal = qty * price;
  totalPartsPrice += subtotal;

  return {
    description: p.longDescription || p.shortDescription || null,
    quantity: qty,
    unitPrice: price,
    subtotal,
  };
});

// Mano de obra
const labor = toNumber(svc.costLabor);

// Precio total = mano de obra + repuestos
const totalPrice = labor + totalPartsPrice;

// Agregar items adicionales fijos
includedItems.push(
  {
    description: "Control de 25 puntos de seguridad",
    quantity: 1,
    unitPrice: 0,
    subtotal: 0,
  },
  {
    description: "Lectura de códigos de falla con scanner FORD",
    quantity: 1,
    unitPrice: 0,
    subtotal: 0,
  }
);
// Armamos salida simple
const result = {
  serviceId: svc.serviceId,
  serviceCode: svc.service,             // ej: SM01
  serviceDescription: svc.serviceDescription,
  monthService: svc.monthService,

  totalPrice,

  includes: includedItems,
};

return [
  {
    json: result,
  },
];

// 1. Obtener la campaña activa del nodo anterior (Get Campaigns1)
const campaignData = $input.first().json;
const campaigns = campaignData.response || [];
const campaign = campaigns.find(c => c.active === true) || campaigns[0] || null;

// 2. Obtener el servicio formateado desde Code9
let service = {};
try {
  service = $('Code9').first().json;
} catch (e) {
  // Fallbacks por si se renombra el nodo
  try {
    service = $('Code').first().json;
  } catch (err) {
    service = {};
  }
}

// 3. Cálculo de precios y descuentos
const originalPrice = service.totalPrice || 0;
let discountPercent = 0;
let discountAmount = 0;
let finalPrice = originalPrice;

if (campaign) {
  if (campaign.discountTypeC === 'PER') {
    discountPercent = campaign.discountValueA || 0;
    discountAmount = Math.round((originalPrice * discountPercent) / 100);
  } else {
    discountAmount = campaign.discountValueA || 0;
    discountPercent = originalPrice > 0 ? Math.round((discountAmount / originalPrice) * 100) : 0;
  }
  finalPrice = originalPrice - discountAmount;
}

// 4. Salida unificada completa
return [
  {
    json: {
      serviceId: service.serviceId || null,
      serviceCode: service.serviceCode || null,
      serviceDescription: service.serviceDescription || null,
      monthService: service.monthService || null,
      pricing: {
        originalPrice: originalPrice,
        discountPercent: discountPercent,
        discountAmount: discountAmount,
        finalPrice: finalPrice
      },
      campaign: campaign ? {
        id: campaign.id,
        name: campaign.campaignN,
        shortDescription: campaign.campaignShortDescriptionN,
        longDescription: campaign.campaignLongDescriptionN,
        discountType: campaign.discountTypeC,
        discountValue: campaign.discountValueA
      } : null,
      includes: service.includes || []
    }
  }
];

// km viene del trigger/input del workflow
const kmRaw = $('When Executed by Another Workflow').first().json.km || 0;

// km_frequency viene del nodo de base de datos (agenda_ford)
const dbData = $('Select rows from a table2').first().json;
const kmFrequency = dbData.km_frequency || 15000;

if (!kmRaw || kmRaw === 0) {
  throw new Error('El campo km es requerido y debe ser mayor a 0');
}
if (!kmFrequency || kmFrequency === 0) {
  throw new Error('km_frequency no puede ser 0 ni null');
}

// Redondear km al múltiplo de km_frequency más cercano (mínimo km_frequency)
const kmRedondeado = Math.max(kmFrequency, Math.round(kmRaw / kmFrequency) * kmFrequency);

// Cálculo del número de servicio y meses
const serviceNumber = Math.round(kmRedondeado / kmFrequency);
const months = Math.max(12, serviceNumber * 12); // mínimo 12

return [
  {
    json: {
      km_original: kmRaw,
      km_redondeado: kmRedondeado,
      km_frequency: kmFrequency,
      service_number: serviceNumber,
      months,
    }
  }
];

