// ==========================================================
// Code33 - Payload Dinámico para Creación de Reserva
// ==========================================================

function toHourNumber(hora) {
  const str = String(hora).trim().replace(':', '');
  return Number(str);
}

function cleanHHMM(hora) {
  return String(hora).trim().replace(':', '').padStart(4, '0');
}

function getCreateSTimestamp() {
  const now = new Date();
  const iso = now.toISOString();
  return `${iso.slice(0, 19)}.${String(now.getMilliseconds()).padStart(3, '0')}0`;
}

// 1. Nodos de origen de datos
const code13 = $('Code13').first().json;
const tabla = $('Select rows from a table4').first().json;
const trigger = $('When Executed by Another Workflow').first().json;
const cotizacionNode = $('HTTP Request31').first().json;

// 2. Horarios y Fechas
const scheduleDate = code13.fecha;
const rawRecepcionHour = code13.horarioRecepcion;
const scheduleHourNum = toHourNumber(rawRecepcionHour);

// 3. Resolución dinámica del Asesor desde Code39
const itemsCode39 = $('Code39').all().map(i => i.json);
const nombreAsesorTrigger = (trigger.nombre_asesor || code13.asesorNombre || "").toLowerCase().trim();

let matchAsesor = itemsCode39.find(a => 
  (a.advisorName || "").toLowerCase().includes(nombreAsesorTrigger) &&
  (a.Slots_Libres || []).includes(rawRecepcionHour)
);

if (!matchAsesor) {
  matchAsesor = itemsCode39.find(a => (a.Slots_Libres || []).includes(rawRecepcionHour));
}

const advisorId = matchAsesor ? Number(matchAsesor.advisorId) : Number(tabla.advisorId);

// 4. Mecánico y Especialidad de Taller
const productiveId = Number(code13.mecanicoId);
const productiveAttendanceHour = cleanHHMM(code13.productiveAttendanceHour);
const productiveAttendanceEndHour = cleanHHMM(code13.productiveAttendanceEndHour);

// ID de especialidad para el taller (id: 5 = Mantenimiento)
const serviceTypeIdWorkshop = Number(code13.specialtyIds?.[0] || 5);

// 5. Cotización y Servicios Ofrecidos
const quotationScheduleVO = cotizacionNode.result?.quotationScheduleVO || cotizacionNode.quotationScheduleVO;
const serviceIdComercial = Number(quotationScheduleVO.quotationVOs[0].serviceId);

// 6. Concesionario, Vehículo y Cliente
const dealerCode = Number(tabla.sucursal);
const customerId = Number(tabla.customerK);
const vehiclePlate = trigger.patente || tabla.plate;
const vehicleVin = tabla.chassi;
const modelGroup = Number(tabla.model_id);
const userCreate = String(tabla.createUser);

// 7. Armado del payload con la estructura exacta de la API
const payload = {
  country: "ARG",
  dealer: dealerCode,
  scheduleDate: scheduleDate,
  scheduleHour: scheduleHourNum,
  vin: vehicleVin,
  offeredServices: [serviceIdComercial],
  quotationScheduleVO: quotationScheduleVO,
  advisor: advisorId,
  createUser: userCreate,
  sendEmail: true,
  contactCountry: "ARG",
  vehiclePlate: vehiclePlate,
  contactCustomerId: customerId,
  customerId: customerId,
  isDriverInformation: null,
  scheduleSource: "D",
  scheduleType: "R",
  model: "",
  group: modelGroup,
  createS: getCreateSTimestamp(),
  campaignsId: [],
  lastKm: null,
  oilLifeRemaining: null,
  iolmMonths: null,
  referredBy: 0,
  scheduleWorkshop: [
    {
      openSchedule: false,
      noShow: false,
      productiveId: productiveId,
      productiveAttendanceHour: productiveAttendanceHour,
      productiveAttendanceEndHour: productiveAttendanceEndHour,
      productiveAttendance: scheduleDate,
      assignedService: [
        {
