// Si tipoService = "mantenimiento", se omiten TODOS los turnos de Horacio Sammarco
// (tanto si figura como asesor como si figura como mecánico).
const excluirHoracioSammarco = tipoService === 'mantenimiento';

function esHoracioSammarco(nombre) {
  if (!nombre) return false;
  const n = normalizarTexto(nombre);
  return n.includes('horacio') && n.includes('sammarco');
}

// ---------- Separar items que llegan desde el Merge ----------
const itemsCombinados = $input.all().map(i => i.json);

const listaAsesores = itemsCombinados.filter(item => item.detalleAsesores || item.totalAsesoresConDisponibilidad !== undefined);
const listaMecanicos = itemsCombinados.filter(item => item.huecosLibres || item.servicios || item.specialtyIds);

// Indexar mecánicos disponibles por fecha (SOLO Mantenimiento)
const agendaMecanicos = {};
for (const m of listaMecanicos) {
  const f = m.fecha || m.fechaActual;
  if (!f) continue;

  // Omitir a Horacio Sammarco si el servicio es Mantenimiento
  if (excluirHoracioSammarco && esHoracioSammarco(m.advisorName)) continue;

  // Validación: Solo mecánicos con especialidad Mantenimiento (id 5)
  const servicios = (m.servicios || []).map(s => normalizarTexto(s));
  const specialtyIds = m.specialtyIds || [];
  const esDeMantenimiento = specialtyIds.includes(5) || servicios.some(s => s.includes("mantenimiento"));

  if (!esDeMantenimiento) continue;

  if (!agendaMecanicos[f]) {
    agendaMecanicos[f] = [];
  }

  const intervalos = [];
  (m.huecosLibres || []).forEach(rango => {
    const partes = rango.split(/[-–—]/).map(s => s.trim());
    if (partes.length === 2) {
      const ini = toMinutes(partes[0]);
      const fin = toMinutes(partes[1]);
      if (ini !== null && fin !== null) {
        intervalos.push([ini, fin]);
      }
    }
  });

  agendaMecanicos[f].push({
    nombre: m.advisorName,
    intervalos
  });
}

const turnosDisponibles = [];
const turnosPorFecha = {};

// Intenta asignar un mecánico a un slot de recepción de un asesor.
// Devuelve el turno armado (y descuenta el hueco del mecánico) o null si no hay match.
function intentarAsignar(fecha, asesor, slotRecepcion, mecanicosDelDia) {
  const minRecepcion = toMinutes(slotRecepcion);
  if (minRecepcion === null) return null;

  for (const mec of mecanicosDelDia) {
    for (let i = 0; i < mec.intervalos.length; i++) {
      const [iniMec, finMec] = mec.intervalos[i];

      const inicioAtencion = Math.max(minRecepcion, iniMec);
      const finAtencion = inicioAtencion + DURACION_SERVICIO_MINUTOS;
      const diferenciaEspera = inicioAtencion - minRecepcion;

      if (
        diferenciaEspera >= 0 &&
        diferenciaEspera <= DIFERENCIA_MAXIMA_MINUTOS &&
        finAtencion <= finMec &&
        finAtencion <= HORA_LIMITE_FIN_MINUTOS
      ) {
        // Descontar intervalo consumido del mecánico
        const nuevosIntervalos = [];
        if (inicioAtencion > iniMec) nuevosIntervalos.push([iniMec, inicioAtencion]);
        if (finMec > finAtencion) nuevosIntervalos.push([finAtencion, finMec]);
        mec.intervalos.splice(i, 1, ...nuevosIntervalos);

        return {
          json: {
            fecha,
            horarioRecepcion: slotRecepcion,
            asesorId: asesor.advisorId,
            asesorNombre: asesor.advisorName,
            mecanicoNombre: mec.nombre,
            huecoMecanico: `${toHHMM(inicioAtencion)} - ${toHHMM(finAtencion)}`,
            diferenciaEsperaMinutos: diferenciaEspera
          }
        };
      }
    }
  }
  return null;
}

// Cruzar disponibilidad Asesor - Mecánico
// Los turnos del día se reparten en rondas entre TODOS los asesores (uno por vuelta),
// y el asesor con el que arranca cada día va rotando para que no salga siempre el mismo.
let indiceDia = 0;

for (const diaAsesor of listaAsesores) {
  const fecha = diaAsesor.fecha || diaAsesor.fechaActual;
  if (!fecha) continue;

  if (fecha === fechaHoy) continue;
  if (!fechaCoincideConFiltro(fecha, fechaEspecifica)) continue;

  const mecanicosDelDia = agendaMecanicos[fecha] || [];
  if (mecanicosDelDia.length === 0) continue;

  // Asesores del día (omitiendo a Horacio Sammarco si el servicio es Mantenimiento)
  const asesoresDia = (diaAsesor.detalleAsesores || []).filter(
    a => !(excluirHoracioSammarco && esHoracioSammarco(a.advisorName))
  );
  if (asesoresDia.length === 0) continue;

  // Rotación del asesor inicial según el día
  const offset = indiceDia % asesoresDia.length;
  indiceDia++;
  const asesoresOrdenados = [...asesoresDia.slice(offset), ...asesoresDia.slice(0, offset)];

  if (!turnosPorFecha[fecha]) turnosPorFecha[fecha] = 0;

  const punteros = asesoresOrdenados.map(() => 0); // próximo slot a probar de cada asesor
  const horariosOfrecidos = new Set();              // evita ofrecer dos veces la misma hora el mismo día

  let huboAsignacion = true;
  while (turnosPorFecha[fecha] < MAX_TURNOS_POR_DIA && huboAsignacion) {
    huboAsignacion = false;

    for (let k = 0; k < asesoresOrdenados.length; k++) {
      if (turnosPorFecha[fecha] >= MAX_TURNOS_POR_DIA) break;

      const asesor = asesoresOrdenados[k];
      const slots = asesor.slotsDisponibles || [];

      // Buscar el próximo slot de este asesor que sirva
      while (punteros[k] < slots.length) {
        const slotRecepcion = slots[punteros[k]++];
        const minRecepcion = toMinutes(slotRecepcion);
        if (minRecepcion === null) continue;

        // La recepción no puede exceder las 13:00 para garantizar que el servicio finalice a las 14:00 o antes
        if (minRecepcion + DURACION_SERVICIO_MINUTOS > HORA_LIMITE_FIN_MINUTOS) continue;
        if (!horaCoincideConFiltro(slotRecepcion, horaEspecifica)) continue;
        if (horariosOfrecidos.has(slotRecepcion)) continue;

        const turno = intentarAsignar(fecha, asesor, slotRecepcion, mecanicosDelDia);
        if (turno) {
          turnosDisponibles.push(turno);
          turnosPorFecha[fecha]++;
          horariosOfrecidos.add(slotRecepcion);
          huboAsignacion = true;
          break; // pasa al siguiente asesor (rotación)
        }
      }
    }
  }
}

if (turnosDisponibles.length === 0) {
  return [{
    json: {
      turnosEncontrados: 0,
      mensaje: "No hay turnos disponibles para los filtros solicitados"
    }
  }];
}

// Ordenar por fecha y horario de recepción
turnosDisponibles.sort((a, b) =>
  a.json.fecha.localeCompare(b.json.fecha) ||
  toMinutes(a.json.horarioRecepcion) - toMinutes(b.json.horarioRecepcion)
);

return turnosDisponibles;

const fechaActual = $('Loop Over Items5').item.json.date;

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

const inputData = $input.first()?.json?.result?.advisorDealerSchedule;
const interval = inputData?.interval || 20;
const advisors = inputData?.advisors || [];

const resultado = advisors.map(a => {
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  // 1. Filtrar daysOffs aplicables para la fecha actual
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  const slotsBloqueadosSet = new Set();

  // Si tiene descanso todo el día, se bloquean todos los slots de su jornada
  const tieneDiaLibreCompleto = daysOffActivos.some(off => off.allDay);
  if (tieneDiaLibreCompleto) {
    gridCompleto.forEach(s => slotsBloqueadosSet.add(s));
  } else {
    // Bloqueos por franja horaria de daysOffs
    daysOffActivos.forEach(off => {
      if (off.offStartHour && off.offEndHour) {
        const slotsOff = generarSlots(off.offStartHour, off.offEndHour, interval);
        slotsOff.forEach(s => slotsBloqueadosSet.add(s));
      }
    });
  }

  // 2. Bloqueos por nonScheduled (sin cita)
  (a.nonScheduled || []).forEach(s => {
    if (s.passerbyHour) slotsBloqueadosSet.add(s.passerbyHour);
  });

  // Ordenar los slots bloqueados
  const slotsOcupados = Array.from(slotsBloqueadosSet).sort((a, b) => toMinutes(a) - toMinutes(b));

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Bloqueados: slotsOcupados,
      Cantidad_Slots_Bloqueados: slotsOcupados.length
    }
  };
});

