// 3. Cálculo de precios y descuentos
const originalPrice = service.totalPrice || 0;
let discountPercent = 0;
let discountAmount = 0;
let finalPrice = originalPrice;

if (campaign) {
  if (campaign.discountTypeC === 'PER') {
    discountPercent = campaign.discountValueA || 0;
    discountAmount = Math.round((originalPrice * discountPercent) / 100);
  } else {
    discountAmount = campaign.discountValueA || 0;
    discountPercent = originalPrice > 0 ? Math.round((discountAmount / originalPrice) * 100) : 0;
  }
  finalPrice = originalPrice - discountAmount;
}

// 4. Salida unificada completa
