// ==========================================================
// Code33 - Payload Dinámico para Creación de Reserva
// ==========================================================

function toHourNumber(hora) {
  const str = String(hora).trim().replace(':', '');
  return Number(str);
}

function cleanHHMM(hora) {
  return String(hora).trim().replace(':', '').padStart(4, '0');
}

function getCreateSTimestamp() {
  const now = new Date();
  const iso = now.toISOString();
  return `${iso.slice(0, 19)}.${String(now.getMilliseconds()).padStart(3, '0')}0`;
}

// 1. Nodos de origen de datos
const code13 = $('Code13').first().json;
const tabla = $('Select rows from a table4').first().json;
const trigger = $('When Executed by Another Workflow').first().json;
const cotizacionNode = $('HTTP Request31').first().json;

// 2. Horarios y Fechas
const scheduleDate = code13.fecha;
const rawRecepcionHour = code13.horarioRecepcion;
const scheduleHourNum = toHourNumber(rawRecepcionHour);

// 3. Resolución dinámica del Asesor desde Code39
const itemsCode39 = $('Code39').all().map(i => i.json);
const nombreAsesorTrigger = (trigger.nombre_asesor || code13.asesorNombre || "").toLowerCase().trim();

let matchAsesor = itemsCode39.find(a => 
  (a.advisorName || "").toLowerCase().includes(nombreAsesorTrigger) &&
  (a.Slots_Libres || []).includes(rawRecepcionHour)
);

if (!matchAsesor) {
  matchAsesor = itemsCode39.find(a => (a.Slots_Libres || []).includes(rawRecepcionHour));
}

const advisorId = matchAsesor ? Number(matchAsesor.advisorId) : Number(tabla.advisorId);

// 4. Mecánico y Especialidad de Taller
const productiveId = Number(code13.mecanicoId);
const productiveAttendanceHour = cleanHHMM(code13.productiveAttendanceHour);
const productiveAttendanceEndHour = cleanHHMM(code13.productiveAttendanceEndHour);

// ID de especialidad para el taller (id: 5 = Mantenimiento)
const serviceTypeIdWorkshop = Number(code13.specialtyIds?.[0] || 5);

// 5. Cotización y Servicios Ofrecidos
const quotationScheduleVO = cotizacionNode.result?.quotationScheduleVO || cotizacionNode.quotationScheduleVO;
const serviceIdComercial = Number(quotationScheduleVO.quotationVOs[0].serviceId);

// 6. Concesionario, Vehículo y Cliente
const dealerCode = Number(tabla.sucursal);
const customerId = Number(tabla.customerK);
const vehiclePlate = trigger.patente || tabla.plate;
const vehicleVin = tabla.chassi;
const modelGroup = Number(tabla.model_id);
const userCreate = String(tabla.createUser);

// 7. Armado del payload con la estructura exacta de la API
const payload = {
  country: "ARG",
  dealer: dealerCode,
  scheduleDate: scheduleDate,
  scheduleHour: scheduleHourNum,
  vin: vehicleVin,
  offeredServices: [serviceIdComercial],
  quotationScheduleVO: quotationScheduleVO,
  advisor: advisorId,
  createUser: userCreate,
  sendEmail: true,
  contactCountry: "ARG",
  vehiclePlate: vehiclePlate,
  contactCustomerId: customerId,
  customerId: customerId,
  isDriverInformation: null,
  scheduleSource: "D",
  scheduleType: "R",
  model: "",
  group: modelGroup,
  createS: getCreateSTimestamp(),
  campaignsId: [],
  lastKm: null,
  oilLifeRemaining: null,
  iolmMonths: null,
  referredBy: 0,
  scheduleWorkshop: [
    {
      openSchedule: false,
      noShow: false,
      productiveId: productiveId,
      productiveAttendanceHour: productiveAttendanceHour,
      productiveAttendanceEndHour: productiveAttendanceEndHour,
      productiveAttendance: scheduleDate,
      assignedService: [
        {
          id: serviceTypeIdWorkshop,
          duration: 60
        }
      ],
      status: "SCHEDULED",
      statusSchedule: "SCHEDULED",
      delay: false,
      height: 138.88888888888889
    }
  ]
};

return [{
  json: {
    body: payload
  }
}];

// ==========================================================
// Code13 - Selección de 1 Único Mecánico de Mantenimiento
// ==========================================================

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const match = String(hhmm).match(/(\d{1,2}):(\d{2})/);
  if (!match) return null;
  return parseInt(match[1], 10) * 60 + parseInt(match[2], 10);
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

// 1. Obtener datos del trigger y de la tabla seleccionada
let trigger = {};
try {
  trigger = $('When Executed by Another Workflow').first()?.json || {};
} catch (e) {}

let tabla = {};
try {
  tabla = $('Select rows from a table4').first()?.json || {};
} catch (e) {}

const fechaActual = trigger.fechaElegida || trigger.date || tabla.selected_date || "2026-09-08";
const horaRecepcionStr = trigger.hour || trigger.selected_hour || tabla.selected_hour || "12:40";
const horaRecepcionMin = toMinutes(horaRecepcionStr);
const nombreAsesorElegido = trigger.nombre_asesor || tabla.advisorName || null;

// 2. Extraer especialistas y schedules del input
const inputItem = $input.first()?.json;
const data = inputItem?.result || inputItem;
const specialists = data?.technicalSpecialists || [];
const schedules = data?.schedules || [];

const mecanicosCalculados = [];

for (const esp of specialists) {
  const specialtyIds = (esp.specialties || []).map(s => s.id);
  const serviciosNombres = (esp.specialties || []).map(s => s.name);

  // FILTRO OBLIGATORIO: Solo mecánicos habilitados para "Mantenimiento" (id 5)
  const esDeMantenimiento = specialtyIds.includes(5) || serviciosNombres.some(s => s.toLowerCase().includes("mantenimiento"));
  if (!esDeMantenimiento) {
    continue;
  }

  const firstShift = esp.workSchedule?.firstShift;
  const secondShift = esp.workSchedule?.secondShift;

  if (esp.availability?.totallyUnavailable || (!firstShift && !secondShift)) {
    continue;
  }

  // Bloqueos por indisponibilidad
  const unavailableList = esp.availability?.unavailableTimes || esp.availability?.unavailablePeriods || [];
  const bloqueosIndisponibilidad = unavailableList
    .map(p => {
      const ini = toMinutes(p.startTime || p.start || p.entry);
      const fin = toMinutes(p.endTime || p.end || p.exit);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  // Bloqueos por turnos ya agendados en taller
  const citasAgendadas = schedules
    .filter(s => s.productiveId === esp.advisorId || s.advisorId === esp.advisorId)
    .map(s => {
      const ini = toMinutes(s.startTime || s.start);
      const fin = toMinutes(s.endTime || s.end);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  const ocupados = [...bloqueosIndisponibilidad, ...citasAgendadas].sort((a, b) => a[0] - b[0]);

  const turnosTrabajo = [];
  if (firstShift?.entry && firstShift?.exit) {
    turnosTrabajo.push([toMinutes(firstShift.entry), toMinutes(firstShift.exit)]);
  }
  if (secondShift?.entry && secondShift?.exit) {
    turnosTrabajo.push([toMinutes(secondShift.entry), toMinutes(secondShift.exit)]);
  }

  // Calcular intervalos libres
  const huecos = [];
  for (const [inicioTurno, finTurno] of turnosTrabajo) {
    let cursor = inicioTurno;
    for (const [ini, fin] of ocupados) {
      if (fin <= cursor || ini >= finTurno) continue;
      if (ini > cursor) {
        huecos.push([cursor, Math.min(ini, finTurno)]);
      }
      cursor = Math.max(cursor, fin);
    }
    if (cursor < finTurno) {
      huecos.push([cursor, finTurno]);
    }
  }

  // Ventana de 0 a 60 min y duración de 60 min
  const DURACION_SERVICIO = 60;
  const DIFERENCIA_MAXIMA = 60;

  for (const [iniHueco, finHueco] of huecos) {
    const inicioAtencion = Math.max(horaRecepcionMin, iniHueco);
    const finAtencion = inicioAtencion + DURACION_SERVICIO;
    const diffEspera = inicioAtencion - horaRecepcionMin;

    if (diffEspera >= 0 && diffEspera <= DIFERENCIA_MAXIMA && finAtencion <= finHueco) {
      mecanicosCalculados.push({
        fecha: fechaActual,
        horarioRecepcion: horaRecepcionStr,
        asesorNombre: nombreAsesorElegido,
        mecanicoId: esp.advisorId,
        mecanicoNombre: esp.advisorName,
        servicios: serviciosNombres,
        specialtyIds: specialtyIds,
        productiveAttendanceHour: toHHMM(inicioAtencion),
        productiveAttendanceEndHour: toHHMM(finAtencion),
        huecoMecanico: `${toHHMM(inicioAtencion)} - ${toHHMM(finAtencion)}`,
        diferenciaEsperaMinutos: diffEspera
      });
      break;
    }
  }
}

// Si no hay mecánicos de mantenimiento disponibles
if (mecanicosCalculados.length === 0) {
  return [{
    json: {
      fecha: fechaActual,
      horarioRecepcion: horaRecepcionStr,
      encontrado: false,
      mensaje: "No se encontraron mecánicos de mantenimiento disponibles en el rango horario solicitado"
    }
  }];
}

// Ordenar por menor tiempo de espera y tomar ÚNICAMENTE el primer mecánico
mecanicosCalculados.sort((a, b) => a.diferenciaEsperaMinutos - b.diferenciaEsperaMinutos);

return [{
  json: mecanicosCalculados[0]
}];

// ==========================================================
// Code31 - Cálculo de Slots Libres por Asesor (Fecha Puntual / Loop)
// ==========================================================

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const match = String(hhmm).match(/(\d{1,2}):(\d{2})/);
  if (!match) return null;
  return parseInt(match[1], 10) * 60 + parseInt(match[2], 10);
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

// Obtener fecha actual desde el Loop o fallback
let fechaActual = null;
try {
  fechaActual = $('Loop Over Items5').item?.json?.date;
} catch (e) {}

if (!fechaActual) {
  try {
    fechaActual = $('Select rows from a table4').first()?.json?.selected_date;
  } catch (e) {}
}

const inputData = $input.first()?.json?.result?.advisorDealerSchedule;
const interval = inputData?.interval || 20;
const advisors = inputData?.advisors || [];

// Fallback de fecha usando el primer dealerSchedule si no vino por variable
if (!fechaActual && advisors.length > 0) {
  fechaActual = advisors[0]?.dealerSchedule?.[0]?.dateSchedule || new Date().toISOString().split('T')[0];
}

const resultado = advisors.map(a => {
  // 1. Filtrar días libres / ausencias vigentes en esta fecha
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  // Si tiene el día completo libre, retorna 0 disponibles
  if (daysOffActivos.some(off => off.allDay)) {
    return {
      json: {
        fechaActual,
        advisorId: a.advisorId,
        advisorName: a.advisorName,
        Slots_Libres: [],
        Cantidad_Slots_Libres: 0
      }
    };
  }

  // 2. Slots bloqueados por franja horaria de daysOffs
  const slotsDaysOff = new Set();
  daysOffActivos.forEach(off => {
    if (off.offStartHour && off.offEndHour) {
      generarSlots(off.offStartHour, off.offEndHour, interval).forEach(s => slotsDaysOff.add(s));
    }
  });

  // 3. Bloqueados sin cita (passerby)
  const reservadosSinCita = new Set((a.nonScheduled || []).map(s => s.passerbyHour).filter(Boolean));

  // 4. Turnos asignados específicamente en esta fecha
  const asignados = new Set(
    (a.dealerSchedule || [])
      .filter(s => s.dateSchedule === fechaActual && s.hourSchedule)
      .map(s => s.hourSchedule)
  );

  // 5. Grilla completa de trabajo del asesor
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  // 6. Exclusión de ocupados
  const slotsLibres = gridCompleto.filter(h => 
    !reservadosSinCita.has(h) && 
    !asignados.has(h) && 
    !slotsDaysOff.has(h)
  );

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Libres: slotsLibres,
      Cantidad_Slots_Libres: slotsLibres.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Libres: [],
      Cantidad_Slots_Libres: 0
    }
  }];
}

return resultado;

// ==========================================================
// Bloques Ocupados - Fecha Puntual
// ==========================================================

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
